import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(aLine[i]);
        }

        int splitPoint = n / 2;
        List<Long> part1 = new ArrayList<>();
        List<Long> part2 = new ArrayList<>();

        // Generate all subset sums for first half
        createSums1(a, 0, 0, splitPoint, m, part1);
        // Generate all subset sums for second half
        createSums2(a, splitPoint, n, 0, m, part2);

        // Remove duplicates and sort part1
        TreeSet<Long> setPart1 = new TreeSet<>(part1);
        List<Long> sortedPart1 = new ArrayList<>(setPart1);

        long max_value = 0;

        for (long val : part2) {
            long target = m - val;
            int index = Collections.binarySearch(sortedPart1, target);
            if (index < 0) {
                index = -index - 1;
            }
            if (index > 0) {
                long candidate_value = sortedPart1.get(index - 1) + val;
                if (candidate_value > max_value) {
                    max_value = candidate_value;
                }
            }
        }
        System.out.println(max_value);
    }

    private static void createSums1(long[] a, int start, int end, int limit, int m, List<Long> result) {
        generateSums(a, start, end, 0, m, result);
    }

    private static void createSums2(long[] a, int start, int end, int index, int m, List<Long> result) {
        generateSums(a, start, end, index, m, result);
    }

    private static void generateSums(long[] a, int start, int end, int currentIndex, int m, List<Long> result) {
        if (currentIndex == end) {
            result.add(0L);
            return;
        }
        // Generate sums including a[currentIndex]
        List<Long> withCurrent = new ArrayList<>();
        generateSums(a, start, end, currentIndex + 1, m, withCurrent);
        for (Long sum : withCurrent) {
            long newSum = (sum + a[currentIndex]) % m;
            result.add(newSum);
        }
        // Generate sums excluding a[currentIndex]
        generateSums(a, start, end, currentIndex + 1, m, result);
    }
